212	export class People {
213	  private readonly http = inject(HttpClient);
214	  private readonly session = inject(Session);
215	  protected readonly rates = inject(RateStore);
216	  private readonly periods = inject(PeriodStore);
217	  protected readonly settings = inject(SettingStore);
218	  /** The sheet's floor in cents. */
219	  protected readonly floor = computed(() => cents(this.settings.floor()));
220	  /** What late charges work from: the sheet's late percent, terms and today. */
221	  private readonly late = computed<Late>(() => ({
222	    pct: this.settings.latePct(),
223	    terms: this.settings.terms(),
224	    today: this.session.today(),
225	  }));
226	
227	  protected readonly grades = ['A', 'B', 'C'];
228	  protected readonly people = signal<Person[]>([]);
229	  /** Whether retired people are listed; off when the screen opens and kept across sheet loads. */
230	  protected readonly showRetired = signal(false);
231	  /** The people listed: everyone, or only those not retired unless retired people are shown. */
232	  protected readonly shownPeople = computed(() =>
233	    this.showRetired() ? this.people() : this.people().filter((p) => !p.retired),
234	  );
235	  /** The retirement date typed on each person's row, by person id. */
236	  protected readonly retireDates = signal<Record<number, string>>({});
237	  /** The sheet's claims, newest first. */
238	  protected readonly claims = signal<Claim[]>([]);
239	  /** The sheet's claims that count in live totals: OPEN and SETTLED ones, except a held person's
240	   *  OPEN ones. */
241	  private readonly live = computed(() => {
242	    const held = new Set(this.people().filter((p) => p.held).map((p) => p.id));
243	    return this.claims().filter((c) => counts(c) && !(c.status === 'OPEN' && held.has(c.personId)));
244	  });
245	  /** Each person's claims that count toward what is claimed and due, by person id. */
246	  private readonly countedByPerson = computed(() => {
247	    const map = new Map<number, Claim[]>();
248	    for (const c of this.live()) map.set(c.personId, [...(map.get(c.personId) ?? []), c]);
249	    return map;
250	  });
251	  /** Each person's claims, newest first, by person id. */
252	  private readonly claimsByPerson = computed(() => {
253	    const map = new Map<number, Claim[]>();
254	    for (const c of this.claims()) map.set(c.personId, [...(map.get(c.personId) ?? []), c]);
255	    return map;
256	  });
257	  protected readonly claimedTotal = computed(() =>
258	    money(this.live().reduce((sum, c) => sum + cents(c.amount), 0)),
259	  );
260	  /** Everyone's due-total added up, skipping those whose grade has no rate. */
261	  protected readonly dueTotal = computed(() =>
262	    money(
263	      this.people().reduce((sum, p) => {
264	        const due = this.dueCentsBy(p);
265	        return due === null ? sum : sum + due;
266	      }, 0),
267	    ),
268	  );
269	  /** Each person's claims that count and are overdue, by person id. */
270	  private readonly overdueByPerson = computed(() => {
271	    const terms = this.settings.terms();
272	    const today = this.session.today();
273	    const map = new Map<number, Claim[]>();
274	    for (const c of this.live()) {
275	      if (overdue(c, terms, today)) map.set(c.personId, [...(map.get(c.personId) ?? []), c]);
276	    }
277	    return map;
278	  });
279	  /** How many claims that count are overdue on the sheet. */
280	  protected readonly overdueCount = computed(() =>
281	    [...this.overdueByPerson().values()].reduce((n, list) => n + list.length, 0),
282	  );
283	  /** The dues of the sheet's overdue claims that count added up. */
284	  protected readonly overdueTotal = computed(() =>
285	    money(this.people().reduce((sum, p) => sum + this.overdueCentsOf(p), 0)),
286	  );
287	  /** Each period's due-total, by period id: the dues shown on the claims that count in live totals
288	   *  whose date falls in the period (a claim with no figure adds nothing). */
289	  protected readonly periodDueTotals = computed(() => {
290	    const periods = this.periods.periods();
291	    const grades = new Map(this.people().map((p) => [p.id, p.grade]));
292	    const totals = new Map<number, number>(periods.map((p) => [p.id, 0]));
293	    for (const c of this.live()) {
294	      const period = periodOf(periods, c.date);
295	      const grade = grades.get(c.personId);
296	      if (period === null || grade === undefined) continue;
297	      totals.set(period.id, (totals.get(period.id) ?? 0) + (claimDueCents(c, this.rates.of(grade), this.floor(), this.late()) ?? 0));
298	    }
299	    return new Map([...totals].map(([id, due]) => [id, money(due)]));
300	  });
301	  protected readonly name = signal('');
302	  protected readonly grade = signal('A');
303	  protected readonly editingId = signal<number | null>(null);
304	  /** The version of the person the editor loaded. */
305	  private readonly editingVersion = signal(0);
306	  /** Whether a submit is waiting for its answer; a second submit meanwhile is dropped. */
307	  private readonly busy = signal(false);
308	  protected readonly error = signal<string | null>(null);
309	  protected readonly quickName = signal('');
310	  protected readonly quickAmount = signal('');
311	  /** Whether a quick-add is waiting for its answer; a second one meanwhile is dropped. */
312	  private readonly quickBusy = signal(false);
313	  protected readonly quickError = signal<string | null>(null);
314	  /** The error from the last action on a person's row refused, and the person it belongs to. */
315	  protected readonly rowError = signal<{ id: number; message: string } | null>(null);
316	
317	  constructor() {
318	    effect(() => {
319	      const sheet = this.session.sheetId();
320	      const load = this.session.loads();
321	      this.people.set([]);
322	      this.claims.set([]);
323	      this.rowError.set(null);
324	      this.retireDates.set({});
325	      this.reset();
326	      this.quickName.set('');
327	      this.quickAmount.set('');
328	      this.quickError.set(null);
329	      if (sheet) void this.read(sheet, load);
330	    });
331	  }
332	
333	  protected value(event: Event): string {
334	    return (event.target as HTMLInputElement | HTMLSelectElement).value;
335	  }
336	
337	  protected checked(event: Event): boolean {
338	    return (event.target as HTMLInputElement).checked;
339	  }
340	
341	  protected setRetireDate(personId: number, date: string): void {
342	    this.retireDates.update((dates) => ({ ...dates, [personId]: date }));
343	    if (this.rowError()?.id === personId) this.rowError.set(null);
344	  }
