346	  /** Retire a person from the typed date (blank takes the sheet's today); their row then shows it,
347	   *  or leaves the list while retired people are not shown. */
348	  protected async retire(person: Person): Promise<void> {
349	    this.rowError.set(null);
350	    const sheet = this.session.sheetId();
351	    if (!sheet) return;
352	    const from = (this.retireDates()[person.id] ?? '').trim() || null;
353	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`;
354	    try {
355	      const saved = await firstValueFrom(this.http.post<Person>(url, { from }));
356	      if (this.session.sheetId() !== sheet) return;
357	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
358	      this.retireDates.update((dates) => ({ ...dates, [person.id]: '' }));
359	    } catch {
360	      this.rowError.set({ id: person.id, message: `${person.name} could not be retired.` });
361	    }
362	  }
363	
364	  /** Put a person on hold, or take them off hold; their row and the totals then show it. */
365	  protected async toggleHold(person: Person): Promise<void> {
366	    this.rowError.set(null);
367	    const sheet = this.session.sheetId();
368	    if (!sheet) return;
369	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/hold`;
370	    try {
371	      const saved = await firstValueFrom(this.http.post<Person>(url, null));
372	      if (this.session.sheetId() !== sheet) return;
373	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
374	    } catch {
375	      this.rowError.set({
376	        id: person.id,
377	        message: `${person.name} could not be ${person.held ? 'taken off hold' : 'put on hold'}.`,
378	      });
379	    }
380	  }
381	
382	  protected claimsOf(personId: number): Claim[] {
383	    return this.claimsByPerson().get(personId) ?? [];
384	  }
385	
386	  /** A person's OPEN and SETTLED claims; drafts and voided claims do not count. */
387	  private countedOf(personId: number): Claim[] {
388	    return this.countedByPerson().get(personId) ?? [];
389	  }
390	
391	  protected claimedBy(personId: number): string {
392	    return money(this.countedOf(personId).reduce((sum, c) => sum + cents(c.amount), 0));
393	  }
394	
395	  /** The sum of the dues shown on a person's claims that count, or n/a when their grade has no rate
396	   *  in force on the sheet's today and no settled or stated claim of theirs keeps a figure. */
397	  protected dueBy(person: Person): string {
398	    const due = this.dueCentsBy(person);
399	    return due === null ? NO_RATE : money(due);
400	  }
401	
402	  private dueCentsBy(person: Person): number | null {
403	    const counted = this.countedOf(person.id);
404	    const hasRate = this.rates.current().has(person.grade);
405	    if (!hasRate && !counted.some((c) => c.settledDue !== null || (c.stated && c.statedDue !== null))) {
406	      return null;
407	    }
408	    const rates = this.rates.of(person.grade);
409	    const floor = this.floor();
410	    const late = this.late();
411	    return counted.reduce((sum, c) => sum + (claimDueCents(c, rates, floor, late) ?? 0), 0);
412	  }
413	
414	  protected overdueOf(personId: number): Claim[] {
415	    return this.overdueByPerson().get(personId) ?? [];
416	  }
417	
418	  /** The dues of a person's overdue claims that count added up (a claim with no figure adds nothing). */
419	  protected overdueTotalOf(person: Person): string {
420	    return money(this.overdueCentsOf(person));
421	  }
422	
423	  private overdueCentsOf(person: Person): number {
424	    const rates = this.rates.of(person.grade);
425	    const floor = this.floor();
426	    const late = this.late();
427	    return this.overdueOf(person.id).reduce((sum, c) => sum + (claimDueCents(c, rates, floor, late) ?? 0), 0);
428	  }
429	
430	  /** A claim added (listed first) or saved in place. */
431	  protected claimSaved(saved: Claim): void {
432	    this.claims.update((list) =>
433	      list.some((c) => c.id === saved.id)
434	        ? list.map((c) => (c.id === saved.id ? saved : c))
435	        : [saved, ...list],
436	    );
437	  }
438	
439	  /** Take a statement for a person: their row and claims then show what it recorded and bound. */
440	  protected async takeStatement(person: Person): Promise<void> {
441	    this.rowError.set(null);
442	    const sheet = this.session.sheetId();
443	    if (!sheet) return;
444	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement`;
445	    try {
446	      const taken = await firstValueFrom(this.http.post<StatementTaken>(url, null));
447	      if (this.session.sheetId() !== sheet) return;
448	      const bound = new Map(taken.claims.map((c) => [c.id, c]));
449	      this.claims.update((list) => [
450	        ...taken.claims.filter((c) => !list.some((had) => had.id === c.id)),
451	        ...list.map((c) => bound.get(c.id) ?? c),
452	      ].sort((a, b) => b.id - a.id));
453	      const { count, lastDueTotal, lastDate } = taken.statements;
454	      this.people.update((list) =>
455	        list.map((p) =>
456	          p.id === person.id
457	            ? { ...p, statementCount: count, statedTotal: lastDueTotal, statementDate: lastDate }
458	            : p,
459	        ),
460	      );
461	    } catch {
462	      this.rowError.set({ id: person.id, message: `A statement could not be taken for ${person.name}.` });
463	    }
464	  }
465	
466	  protected edit(person: Person): void {
467	    this.rowError.set(null);
468	    this.editingId.set(person.id);
469	    this.editingVersion.set(person.version);
470	    this.name.set(person.name);
471	    this.grade.set(person.grade);
472	    this.error.set(null);
473	  }
474	
475	  protected reset(): void {
476	    this.editingId.set(null);
477	    this.name.set('');
478	    this.grade.set('A');
479	    this.error.set(null);
480	  }
481	
482	  protected async submit(event: Event): Promise<void> {
483	    event.preventDefault();
484	    if (this.busy()) return;
485	    this.error.set(null);
486	    const sheet = this.session.sheetId();
487	    if (!sheet) return;
488	    const body = { name: this.name().trim(), grade: this.grade() };
489	    if (!body.name) {
490	      this.error.set('Type a name for the person.');
491	      return;
492	    }
493	    const id = this.editingId();
494	    const base = `/api/sheets/${encodeURIComponent(sheet)}/people`;
495	    this.busy.set(true);
496	    try {
497	      const saved = await firstValueFrom(
498	        id === null
499	          ? this.http.post<Person>(base, body)
500	          : this.http.put<Person>(`${base}/${id}`, { ...body, version: this.editingVersion() }),
501	      );
502	      if (this.session.sheetId() !== sheet) return;
503	      this.people.update((list) =>
504	        id === null ? [...list, saved] : list.map((p) => (p.id === saved.id ? saved : p)),
505	      );
506	      this.reset();
507	    } catch (e) {
508	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
509	        await this.showCurrent(sheet, id, e.error as Person | null);
510	        this.error.set('Someone else saved this person since you opened the editor; their values are shown.');
511	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
512	        this.error.set(`Another person on the sheet is already named ${body.name}.`);
513	      } else {
514	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
515	      }
516	    } finally {
517	      this.busy.set(false);
518	    }
519	  }
520	
521	  /** Add a DRAFT claim for the named person, adding them (grade A) when the name is not on the
522	   *  sheet; their row and the claim then show. */
523	  protected async quickAdd(event: Event): Promise<void> {
524	    event.preventDefault();
525	    if (this.quickBusy()) return;
526	    this.quickError.set(null);
527	    const sheet = this.session.sheetId();
528	    if (!sheet) return;
529	    const name = this.quickName().trim();
530	    const amount = this.quickAmount().trim();
531	    if (!name) {
532	      this.quickError.set('Type a name for the claim.');
533	      return;
534	    }
535	    if (!AMOUNT.test(amount)) {
536	      this.quickError.set('Type an amount of 0.00 or more, with up to two decimals.');
537	      return;
538	    }
539	    this.quickBusy.set(true);
540	    try {
541	      const added = await firstValueFrom(
542	        this.http.post<{ person: Person; claim: Claim }>(
543	          `/api/sheets/${encodeURIComponent(sheet)}/quick-add`,
544	          { name, amount },
545	        ),
546	      );
547	      if (this.session.sheetId() !== sheet) return;
548	      this.people.update((list) =>
549	        list.some((p) => p.id === added.person.id)
550	          ? list.map((p) => (p.id === added.person.id ? added.person : p))
551	          : [...list, added.person],
552	      );
553	      this.claimSaved(added.claim);
554	      this.quickName.set('');
555	      this.quickAmount.set('');
556	    } catch (e) {
557	      this.quickError.set(
558	        e instanceof HttpErrorResponse && e.status === 409
559	          ? `A claim for ${name} could not be added: its date falls in a closed period or after they retired.`
560	          : `A claim for ${name} could not be added.`,
561	      );
562	    } finally {
563	      this.quickBusy.set(false);
564	    }
565	  }
566	
567	  /** After a refused stale save, show the person as stored now, in their row and in the editor,
568	   *  which then holds the version it shows. */
569	  private async showCurrent(sheet: string, id: number, current: Person | null): Promise<void> {
570	    if (!current) {
571	      const list = await firstValueFrom(
572	        this.http.get<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
573	      ).catch(() => []);
574	      current = list.find((p) => p.id === id) ?? null;
575	    }
576	    if (!current || this.session.sheetId() !== sheet) return;
577	    const now = current;
578	    this.people.update((list) => list.map((p) => (p.id === now.id ? now : p)));
579	    if (this.editingId() === now.id) {
580	      this.editingVersion.set(now.version);
581	      this.name.set(now.name);
582	      this.grade.set(now.grade);
583	    }
584	  }
585	
586	  /** Read the sheet's people and claims; a response for an earlier load is dropped. */
587	  private async read(sheet: string, load: number): Promise<void> {
588	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
589	    const [list, claims] = await Promise.all([
590	      firstValueFrom(this.http.get<Person[]>(`${base}/people`)),
591	      firstValueFrom(this.http.get<Claim[]>(`${base}/claims`)),
592	    ]);
593	    if (this.session.loads() !== load) return;
594	    this.people.set(list);
595	    this.claims.set(claims);
596	  }
597	}
